SELECT COUNT(*)
FROM dms_shop_member
WHERE system_account = 0
  AND create_time >= #{startTime}
  AND create_time < #{endTime}

SELECT COALESCE(SUM(GREATEST(shop_order.total_amount - COALESCE(refund.product_refund_amount, 0), 0)), 0)
FROM dms_shop_order shop_order
LEFT JOIN (
    SELECT order_id, COALESCE(SUM(product_refund_amount), 0) AS product_refund_amount
    FROM dms_finance_refund
    GROUP BY order_id
) refund ON refund.order_id = shop_order.id
WHERE shop_order.tenant_id = #{tenantId}
  AND shop_order.pay_time IS NOT NULL

    AND shop_order.pay_time >= #{startTime}


    AND shop_order.pay_time < #{endTime}

SELECT COALESCE(SUM(GREATEST(shop_order.total_amount - COALESCE(refund.product_refund_amount, 0), 0)), 0)
FROM dms_shop_order shop_order
LEFT JOIN (
    SELECT order_id, COALESCE(SUM(product_refund_amount), 0) AS product_refund_amount
    FROM dms_finance_refund
    GROUP BY order_id
) refund ON refund.order_id = shop_order.id
WHERE shop_order.tenant_id = #{tenantId}
  AND shop_order.pay_time IS NOT NULL
  AND shop_order.pay_time >= #{startTime}
  AND shop_order.pay_time < #{endTime}

SELECT COALESCE(SUM(withdraw_amount), 0)
FROM dms_withdraw_record
WHERE status = 3

    AND pay_time >= #{startTime}


    AND pay_time < #{endTime}
